import os
from concurrent import futures

import grpc
import requests

# Generated by `make -f ML/Makefile proto`
from proto_gen import moderation_pb2, moderation_pb2_grpc


def _env(name: str, default: str) -> str:
    v = os.getenv(name)
    return v if v not in (None, "") else default


MODERATION_HTTP_URL = _env("MODERATION_HTTP_URL", "http://localhost:8001/moderate")
GRPC_HOST = _env("GRPC_HOST", "0.0.0.0")
GRPC_PORT = int(_env("GRPC_PORT", "50051"))


class ModerationGateway(moderation_pb2_grpc.ModerationServiceServicer):
    """gRPC -> HTTP gateway for moderation."""

    def Moderate(self, request, context):
        payload = {}
        if request.text:
            payload["text"] = request.text
        if request.image_path:
            payload["image_path"] = request.image_path

        try:
            r = requests.post(MODERATION_HTTP_URL, json=payload, timeout=10)
            r.raise_for_status()
            data = r.json()
        except Exception as e:
            context.set_code(grpc.StatusCode.UNAVAILABLE)
            context.set_details(f"moderation http call failed: {e}")
            return moderation_pb2.ModerateResponse(text_flag=False, image_flag=False)

        return moderation_pb2.ModerateResponse(
            text_flag=bool(data.get("text_flag", False)),
            image_flag=bool(data.get("image_flag", False)),
        )


def serve():
    server = grpc.server(futures.ThreadPoolExecutor(max_workers=16))
    moderation_pb2_grpc.add_ModerationServiceServicer_to_server(ModerationGateway(), server)
    server.add_insecure_port(f"{GRPC_HOST}:{GRPC_PORT}")
    server.start()
    print(f"gRPC gateway listening on {GRPC_HOST}:{GRPC_PORT} -> {MODERATION_HTTP_URL}")
    server.wait_for_termination()


if __name__ == "__main__":
    serve()

